import pathlib,sys,re,json,shutil,hashlib
P=pathlib.Path('/workspace/scratch/module-scope-walk');label=sys.argv[1];r=json.loads((P/(label+'.receipt.json')).read_text());err=(P/(label+'.stderr')).read_text();matches=re.findall(r'Running unittests .*?\(([^)]+)\)',err);assert len(matches)==1,matches;src=pathlib.Path(matches[0]);dst=P/(label+'-tests');assert not dst.exists();shutil.copy2(src,dst);record={'source_head':r['head'],'executed_tree':r['executed_worktree_tree'],'observed_cargo_test_binary':str(src),'retained_binary':dst.name,'bytes':dst.stat().st_size,'sha256':hashlib.file_digest(dst.open('rb'),'sha256').hexdigest(),'command':r['argv'],'native_exit':r['exit'],'CARGO_INCREMENTAL':r['CARGO_INCREMENTAL']};(P/(label+'-binary.json')).write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record,indent=2))
